import{_ as o,l as i,o as e,c as l,v as t,p as s,x as r,d as h,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"动量 WML","description":"","frontmatter":{"title":"动量 WML","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/momentum-wml.md","filePath":"quant/momentum-wml.md","lastUpdated":1789023840000}'),d={name:"quant/momentum-wml.md"};function E(M,a,c,_,u,L){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="动量-wml" tabindex="-1">动量 WML <a class="header-anchor" href="#动量-wml" aria-label="Permalink to &quot;动量 WML&quot;">​</a></h1><div class="epigraph"><p>买入过去三到十二个月的赢家、卖出输家，在随后三到十二个月里仍能获得显著收益；这不是一月反转，也不是三年到五年的长期反转。</p><footer>—— Jegadeesh &amp; Titman, Returns to Buying Winners and Selling Losers, Journal of Finance, 1993</footer></div><p><a href="/quant/ff5">上一课</a>把盈利与投资收成 RMW / CMA，三因子留下的 α 被写成与 SMB/HML 同一套多空语言。五因子小结已经点名：动量仍在模型外。中间 horizon 的相对强度——赢家减输家在 3–12 个月上持续，且与 HML 常常负相关——还没有一条腿。本课钉截面动量 <strong>WML</strong>（12−1）。不重推五因子的 2×3，不从有效市场总问题重开。一个月反转见<a href="/quant/short-term-reversal">反转</a>；动量崩溃另文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五因子右侧已经有市场、规模、价值、盈利、投资。按过去收益排序的组合上仍然有 α。这不是再问「公开信息该不该预测收益」——三因子、五因子已经在特征层面回答过定价核缺哪几条。缺口是这段 <strong>3–12 个月的相对强度</strong>：要不要做成独立多空腿、如何跳过最近一个月以免混进<a href="/quant/short-term-reversal">反转</a>、以及它与 HML 的负相关为什么不能靠 RMW/CMA 吸收。Jegadeesh–Titman 的 J/K 与 Carhart / French 的 WML（UMD）是同一条腿的两种写法。</p><p>赢家往往偏成长、偏高 β，输家偏价值、偏困境；HML 会给出「动量应该为负」的直觉。若只在五因子残差上再回归一次过去收益，诊断到了，定价核没有变。要把相对强度放进右侧，才和上一课把 RMW、CMA 放进右侧是同一句话。</p><h3 id="相对强度不是时间序列趋势" tabindex="-1">相对强度不是时间序列趋势 <a class="header-anchor" href="#相对强度不是时间序列趋势" aria-label="Permalink to &quot;相对强度不是时间序列趋势&quot;">​</a></h3><p>时间序列动量看的是资产自己的过去超额收益是否为正（Moskowitz、Ooi、Pedersen 的期货趋势）。截面 WML 在每个日期把股票排序，多空资金内部对冲，对市场方向的净暴露被设计成接近零。一只绝对收益为负但仍强于同侪的股票可以进赢家组。把 WML 画成「股票市场的均线策略」会在熊市里误判：截面赢家在下跌市里同样在跌，只是跌得少。</p><p><span class="marginnote">标准美股动量用过去 12 个月减去最近 1 个月，记作 12−1。把最近一个月算进去，会把 Jegadeesh 的短期反转混进动量，溢价变弱甚至变号。跳月不是细节，是定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>经典 J/K：在 t 月末按 t−J 到 t 的累计收益排序（或按 t−J 到 t−1，以跳月），等权或价值加权买入前十分位、卖出后十分位，持有 K 个月。重叠持有时，每月组合是 K 个不同 vintage 的等权平均，以降低换手集中。Jegadeesh–Titman 的主表覆盖 J,K ∈ {3,6,9,12}。</p><p>行业惯例的因子口径更接近 French：独立 2×3，规模用 NYSE 中位，动量用 NYSE 的 30%/70%（过去 12−1 月收益），六个价值加权组合上</p> \\[\\mathrm{WML}=\\tfrac12(R_{S/W}+R_{B/W})-\\tfrac12(R_{S/L}+R_{B/L}). \\]<p>Carhart 四因子是三因子加 WML。对组合 \\(i\\)，</p> \\[R_{it}-R_{ft}=\\alpha_i+\\beta_{iM}\\mathrm{MKT}_t+\\beta_{iS}\\mathrm{SMB}_t+\\beta_{iH}\\mathrm{HML}_t+\\beta_{iW}\\mathrm{WML}_t+\\varepsilon_{it}. \\]<p>动量 α 在三因子下显著为正；加入 WML 后，按过去收益排序的检验组合 α 被吸收，但按其他特征排的组合不一定。</p><h3 id="跳月、形成期与持有期" tabindex="-1">跳月、形成期与持有期 <a class="header-anchor" href="#跳月、形成期与持有期" aria-label="Permalink to &quot;跳月、形成期与持有期&quot;">​</a></h3><p>形成期过短会撞上反转与买卖价差反弹；过长会撞上长期反转。12−1 是文献里对美股最稳的折中。持有期一个月、每月再平衡，换手高、容量受流动性约束；持有 6–12 个月并重叠，换手下降，信号变钝。价值加权降低微型股贡献，等权则让动量看起来更强、也更贵。跳过最近一个月还有一个会计原因：财报窗口附近的收益含未预期盈余，短期反转与盈余漂移会打架。</p>',18)),(e(),s(p,null,{default:r(()=>[m(n,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20RET%5B%22%E8%BF%87%E5%8E%BB%2012%20%E4%B8%AA%E6%9C%88%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20SKIP%5B%22%E5%8E%BB%E6%8E%89%E6%9C%80%E8%BF%91%201%20%E4%B8%AA%E6%9C%88%22%5D%0A%20%20SKIP%20--%3E%20RK%5B%22NYSE%20%E5%88%86%E4%BD%8D%E6%8E%92%E5%BA%8F%22%5D%0A%20%20SIZE%5B%22%E8%A7%84%E6%A8%A1%E4%B8%AD%E4%BD%8D%22%5D%20--%3E%20RK%0A%20%20RK%20--%3E%20W%5B%22%E8%B5%A2%E5%AE%B6%E8%85%BF%20S%2FW%20B%2FW%22%5D%0A%20%20RK%20--%3E%20L%5B%22%E8%BE%93%E5%AE%B6%E8%85%BF%20S%2FL%20B%2FL%22%5D%0A%20%20W%20--%3E%20WML%5B%22WML%20%E4%BB%B7%E5%80%BC%E5%8A%A0%E6%9D%83%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20L%20--%3E%20WML%0A%20%20WML%20--%3E%20HOLD%5B%22%E6%8C%81%E6%9C%89%201%20%E6%9C%9F%E6%88%96%20J%2FK%20%E9%87%8D%E5%8F%A0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>风险解释把赢家当成高久期、高增长期权，在好状态下更敏感；输家像困境债。这解释不了为何溢价在形成期之后继续存在、并在市场反弹时剧烈为负（动量崩溃：输家空头在 V 型反转里爆亏）。行为解释是反应不足与趋势追逐：新闻缓慢进入价格，后段又过度外推。Hong–Lim–Stein 的「信息缓慢扩散」与 Daniel 等的过度自信都指向同一段中间 horizon。</p><p>实务上更有操作含义的机制是：<strong>拥挤与强平</strong>。动量腿高度相关，杠杆资金在同一组赢家上叠杠杆；波动率上升时去杠杆先砸赢家，同时回补输家，WML 出现左尾。因此 WML 的均值来自平常月份的温和正收益，夏普被少数崩溃月拉低。任何把 WML 当稳定保险的用法都与历史分布相反。</p><h3 id="行业动量与残差动量" tabindex="-1">行业动量与残差动量 <a class="header-anchor" href="#行业动量与残差动量" aria-label="Permalink to &quot;行业动量与残差动量&quot;">​</a></h3><p>行业等权动量往往更稳、换手更低，因为个股特异噪声被抵消。残差动量先对 <a href="/quant/ff3">Fama-French</a> 回归，再用残差收益排序，意在去掉市场与价值的污染。两者都不是 Jegadeesh–Titman 原文的定义；在因子模型里它们改变的是 WML 与 HML、MKT 的相关，而不是「动量是否存在」。复制时必须先声明排序变量是总收益还是残差。</p><p><span class="marginnote">WML 与 HML 的负相关是配置问题不是笔误。价值-动量组合的分散化在 Asness 等「价值与动量无处不在」里被写成跨资产事实。单看股票 WML 的回撤，会低估它在多因子里的对冲价值，也会低估同时减杠杆时两者一起崩的尾部。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>容量：输家腿多是低流动性、高借券费用的股票，账面溢价含卖空约束。剔除借不到的股票后，WML 变薄。交易成本对等权十分位很致命，对大盘价值加权 2×3 好一些，但仍远高于 HML 的年度再平衡。</p><p>样本：美股 1927 年起即可算动量，崩溃集中在 1932、2009 一类反弹。国际股票、商品、外汇上也有趋势，但不能把期货的时间序列动量夏普直接标在个股 WML 上。A 股的涨跌停与短期投机让 12−1 与一个月反转的相对强弱与美股不同，必须用当地断点重做。</p><p>不要用日内或隔夜收益当「高频动量」却引用 1993 年论文。不要把 12 个月均线金叉当成 WML。因子模型里 WML 的 β 是协方差，一只从未进过赢家组的股票仍可有正动量载荷。</p><p><span class="marginnote">真实出处：Jegadeesh &amp; Titman, Journal of Finance, 1993；Carhart, Journal of Finance, 1997（四因子）。UMD 名称见 Ken French 数据说明。动量崩溃见 Daniel &amp; Moskowitz, Journal of Financial Economics, 2016，不要写进 1993 年正文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>截面动量是 3–12 个月的相对强度，标准因子是跳过最近一个月的 12−1 WML/UMD。</li><li>构造常用规模×动量的 2×3 价值加权；J/K 重叠持有用于降低换手。</li><li>三因子吸不掉动量；WML 与 HML 常负相关，尾部有崩溃。</li><li>卖空成本、借券与微型股会显著侵蚀账面溢价。</li><li>出处：Jegadeesh &amp; Titman, Journal of Finance, 1993；因子化见 Carhart, 1997。</li></ul>',13))])}const W=o(d,[["render",E]]);export{A as __pageData,W as default};
